// Function-Node: S7 records -> Spark metrics (mit Array-Support)

const tagMeta = flow.get('tagMeta') || {};

// Sicherheitscheck
if (!msg.payload || !Array.isArray(msg.payload.records)) {
    return null;   // nichts Sinnvolles -> Nachricht verwerfen
}

const metrics = [];

// alle Records durchgehen (falls später mal mehr als einer kommt)
msg.payload.records.forEach(rec => {
    if (!Array.isArray(rec.vals)) {
        return;
    }

    rec.vals.forEach(e => {
        const meta = tagMeta[e.id];

        // Fall 1: Array-Tag und val ist ein Array -> aufsplitten
        if (meta && meta.isArray && Array.isArray(e.val)) {
            const len = e.val.length;

            for (let i = 0; i < len; i++) {
                metrics.push({
                    name: `${meta.base}[${i}]`,  // z.B. sensor/1[0]
                    value: e.val[i]
                });
            }
        } else {
            // Fall 2: Skalar oder kein Meta -> wie bisher
            const baseName = meta ? meta.base : `sensor/${e.id}`;
            metrics.push({
                name: baseName,      // z.B. sensor/1
                value: e.val         // qc und ts lassen wir weg
            });
        }
    });
});

// Spark-Kontext bauen
msg.payload = {
    metrics: metrics
};

return msg;

// Function-Node: S7-Metadaten -> Spark definition + Tag-Metadaten

const cfg = msg.payload;

if (!cfg || !Array.isArray(cfg.connections)) {
    node.error("Ungültige Metadaten-Struktur", msg);
    return null;
}

// Mapping S7-Datentyp -> Spark-Datentyp (bei Bedarf erweitern)
const typeMap = {
    "Int": "Int32",
    "Int16": "Int16",
    "Int32": "Int32",
    "Real": "Float",
    "Bool": "Boolean"
};

const defs = {};
const tagMeta = {};   // id -> { base, isArray, length }

// alle Verbindungen / Datapoints / Definitions durchlaufen
cfg.connections.forEach(conn => {
    (conn.dataPoints || []).forEach(dp => {
        (dp.dataPointDefinitions || []).forEach(dpd => {

            const baseMetricName = `sensor/${dpd.id}`;
            const dataType = typeMap[dpd.dataType] || "Int32";

            // Array-Erkennung über Namen, z.B. "TestINT5000Array[5000]"
            const m = /^(.*)\[(\d+)\]$/.exec(dpd.name);

            if (dpd.arrayDimensions!=undefined) {
                const length = dpd.arrayDimensions[0]

                tagMeta[dpd.id] = {
                    base: baseMetricName,
                    isArray: true,
                    length: length
                };

                // Für jedes Array-Element eine Metric-Definition anlegen
                for (let i = 0; i < length; i++) {
                    const metricName = `${baseMetricName}[${i}]`;
                    defs[metricName] = {
                        dataType: dataType
                    };
                }
            } else {
                // Skalar wie gehabt
                tagMeta[dpd.id] = {
                    base: baseMetricName,
                    isArray: false
                };

                defs[baseMetricName] = {
                    dataType: dataType
                };
            }
        });
    });
});

// Metadaten im Node-Kontext speichern, damit der Daten-Node sie nutzen kann
flow.set('tagMeta', tagMeta);

// Spark erwartet definition im msg.definition
msg.definition = defs;

// Payload ist optional – leer lassen oder Dummy:
msg.payload = {
    metrics: []
};

return msg;

/**
 * Calculates the approximate size of the msg.payload object in bytes.
 * This is an approximation based on JSON stringification.
 * For more accurate byte size of the raw Sparkplug B message, you'd need
 * to intercept the raw MQTT payload before decoding.
 */

const payloadString = JSON.stringify(msg.payload);
const payloadSizeInBytes = Buffer.byteLength(payloadString, 'utf8');

// You can see this in the Node-RED debug sidebar (under the 'debug' tab)
// and in the Node-RED console log.
node.warn(`Sparkplug B Decoded Payload Size: ${payloadSizeInBytes} bytes`);

// Optionally, modify the msg.payload to include the size for further processing
// or to see it directly in the debug node.
msg.payload = {
    originalPayload: msg.payload, // Keep the original payload for context
    sizeInBytes: payloadSizeInBytes
};

return msg;
